cat > probe_useridx_test.go <<'EOF'
package main

import (
	"testing"
	"time"
)

func TestProbeUserIndex(t *testing.T) {
	store := NewStore(30 * time.Second)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("a", "alice")
	store.Create("b", "alice")
	store.Create("c", "bob")

	if got := store.CountUser("alice"); got != 2 {
		t.Fatalf("alice = %d, want 2", got)
	}
	if got := store.CountUser("bob"); got != 1 {
		t.Fatalf("bob = %d, want 1", got)
	}
	if got := store.CountUser("nobody"); got != 0 {
		t.Fatalf("nobody = %d, want 0", got)
	}

	// Delete decrements the index.
	store.Delete("a")
	if got := store.CountUser("alice"); got != 1 {
		t.Fatalf("alice after delete = %d, want 1", got)
	}

	// Expiry drops also decrement (Get drops expired).
	now = time.Unix(2000, 0) // b(1001) expired
	if _, err := store.Get("b"); err == nil {
		t.Fatal("b should be expired")
	}
	if got := store.CountUser("alice"); got != 0 {
		t.Fatalf("alice after expiry = %d, want 0", got)
	}
	if got := store.CountUser("bob"); got != 1 {
		t.Fatalf("bob still indexed = %d, want 1", got)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_useridx_test.go

# Structural: CountUser must answer from the index, not scan.
src=$(cat session.go)
echo "$src" | grep -q "func (s \*Store) CountUser" || { echo "missing CountUser"; exit 1; }
countbody=$(echo "$src" | sed -n '/func (s \*Store) CountUser/,/^}/p')
if echo "$countbody" | grep -q "range s.sessions"; then echo "CountUser still scans the session map"; exit 1; fi
echo "$src" | grep -q "userCount" || { echo "no secondary index present"; exit 1; }
exit $rc

